// FamilyGuard device enrollment. Called once by the Python agent on a child
// PC with a code generated by the parent in the admin UI. Returns the raw
// device token exactly once; the caller must store it locally.

import { createClient } from 'npm:@supabase/supabase-js@2';
import { sha256Hex } from './hash.ts';

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, content-type',
};

function randomToken(): string {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') {
    return new Response('ok', { headers: cors });
  }
  if (request.method !== 'POST') {
    return Response.json({ error: 'method not allowed' }, { status: 405, headers: cors });
  }

  const body = await request.json().catch(() => null);
  const code = typeof body?.code === 'string' ? body.code.trim().toUpperCase() : '';
  const deviceName = typeof body?.deviceName === 'string' ? body.deviceName.trim() : '';
  const nickname = typeof body?.nickname === 'string' ? body.nickname.trim() : '';

  if (!code || !deviceName) {
    return Response.json({ error: 'code and deviceName are required' }, { status: 400, headers: cors });
  }

  const url = Deno.env.get('SUPABASE_URL');
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !serviceKey) {
    return Response.json({ error: 'server misconfigured' }, { status: 500, headers: cors });
  }

  const admin = createClient(url, serviceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // Only the SHA-256 hex of the token is ever stored server-side.
  const deviceToken = randomToken();
  const tokenHash = await sha256Hex(deviceToken);

  const { data, error } = await admin.rpc('enroll_device', {
    p_code: code,
    p_device_name: deviceName,
    p_nickname: nickname || deviceName,
    p_token_hash: tokenHash,
  });

  if (error) {
    // enroll_device raises 'invalid, used or expired enrollment code'
    const invalid =
      /invalid|used|expired/i.test(error.message) || error.code === 'P0001';
    return Response.json(
      { error: invalid ? 'invalid, used or expired enrollment code' : error.message },
      { status: invalid ? 400 : 500, headers: cors },
    );
  }

  return Response.json(
    {
      deviceToken,
      device: { id: data.device_id, nickname: nickname || deviceName, deviceName },
    },
    { status: 201, headers: cors },
  );
});
